 public BuzCabPresentation cab;public BuzCargoContacts contacts;public SportsEventTruck[] trucks;public Rigidbody cargo;public BoxCollider cargoShape;public Rigidbody[] floppy;public Vector3[] floppyOffsets;public LineRenderer rope;public SportsEventCamera broadcast;public SportsCameraFit framing;public TextMesh[] identities,corralNames;public TMP_InputField[] teamInputs;public string[] teams={"Blue Bandits","Orange Outlaws"};public int[] score=new int[2];public BuzPhase Phase{get;private set;}public int Owner{get;private set;}=-1;public float Clock{get;private set;}public float Age{get;private set;}public bool SuddenDeath{get;private set;}public int Winner{get;private set;}=-1;public int Attachments{get;private set;}public int Breaks{get;private set;}public int Deliveries{get;private set;}public int Recoveries{get;private set;}public int TruckRecoveries{get;private set;}public Vector3[] previousVelocity=new Vector3[6];
 SpringJoint tow;float available,stuckAge,outAge,reclaimUntil,attachProtectedUntil,looseUntil;int previousCarrier=-1;Vector3 lastCargo;readonly float[] think=new float[6],noProgress=new float[6],reverse=new float[6],inverted=new float[6],recovering=new float[6],outsideAge=new float[6];readonly Vector3[] lastTruck=new Vector3[6];readonly Vector2[] ai=new Vector2[6];readonly RaycastHit[] rays=new RaycastHit[64];readonly StringBuilder text=new StringBuilder(1200);int scorer=-1;
