 public override string Title=>"TRUCK BUZKASHI";public override int MinimumPlayers=>6;public override int MaximumPlayers=>6;public override int OptionCount=>2;public override bool MultiViewHUD=>option==1&&cab!=null&&cab.Humans>0;public override bool TeamSport=>true;public override string OptionLabel=>option==0?"SHARED ARENA · TWO TEAMS OF THREE":"FIRST PERSON · FOUR LOCAL HUMAN VIEWS";public override void NormalizeSetup(){base.NormalizeSetup();teamA=teamB=3;setup.count=6;}
 public override bool ValidateSources(out string reason){if(!base.ValidateSources(out reason))return false;int n=0;for(int i=0;i<6;i++)if(setup.players[i].source!=BowlingSource.AI)n++;if(n>4){reason="At most four human sources; AI fills both three-truck teams.";return false;}return true;}
 public override string Help=>"THE GREAT STUFFED-GOAT HEIST\nTwo teams of three trucks contest one oversized, non-gory stuffed sheep. Five minutes, most deliveries wins; a tie continues in sudden death. Up to four local humans, editable individual/team names, independent sources and AI difficulty. Blue owns the near corral; orange the far one.\n\nMOVE drives, steers, brakes then reverses. ACTION near loose cargo with clear line of sight attaches a physical tow rope. ACTION again releases it. One owner, no teleport. Cargo mass affects acceleration and turns; the rope stretches within a bounded length and force and can break. It cannot pass through barriers.\n\nDEFEND OR ESCORT\nA meaningful opposing truck contact into the carrier breaks its rope, using actual incoming normal speed above2.3m/s. Friendly bumps and cosmetic/trigger contacts do not break it. A0.35s new-attachment grace and1.4s previous-carrier reclaim delay prevent instant retakes. Teammates escort, screen and defend; AI uses the same action eligibility and physical motors.\n\nDELIVER THE WHOLE CARGO\nThe entire cargo scoring box must enter YOUR painted corral while a live teammate owns its rope. Truck entry alone or an unowned sheep earns nothing. Each delivery locks once, celebrates, then resets both teams and cargo fairly. Five-minute clock pauses during celebrations/recovery. Cargo outside the actual field for1.5s resets neutrally; immobile unattended cargo resets after12s without an approach. A cargo body genuinely pressed against a solid lateral wall with less than0.65m progress for18s triggers an announced neutral recovery; ordinary open-field crowding does not. A stationary upside-down truck for5s or real out-of-bounds fall receives the same1.5s announced return to an unoccupied home grid for humans and AI; no forward warp or scoring advantage. Score/clock persist.\n\nSelect shared elevated broadcast or independent first-person cabs with owned free look and animated steering. The same assigned action attaches or releases within7m. Pause/disconnect preserves bodies, rope, score and clock. Reconnect or explicitly replace, release controls and freshly confirm. Rematch retains names and source setup. Offline only.";
 public override string Header=>Title+" | "+teams[0]+"  "+score[0]+" : "+score[1]+"  "+teams[1]+" | "+(SuddenDeath?"SUDDEN DEATH":Mathf.CeilToInt(300-Clock)+"s");
 public override string Status=>Phase==BuzPhase.Countdown?Mathf.CeilToInt(3-Age).ToString():Phase==BuzPhase.Celebration?teams[scorer]+" DELIVERS THE WHOLE SHEEP!":Phase==BuzPhase.Recovery?"NEUTRAL CARGO RECOVERY · SCORE AND CLOCK RETAINED":Owner<0?(Clock<looseUntil?"SHEEP LOOSE! · RAM THE CARRIER, THEN RECLAIM":"LOOSE CARGO · APPROACH THE HIGHLIGHT · ACTION TO TOW"):"TOWING: "+setup.players[Owner].name+" · "+teams[BuzRules.Team(Owner)];
 public override string Standings{get{text.Clear();for(int i=0;i<6;i++)text.Append("<color=#").Append(ColorUtility.ToHtmlStringRGB(setup.players[i].color)).Append('>').Append(setup.players[i].name).Append("</color> · ").Append(Recovering(i)?"RECOVERING":i==Owner?"CARRIER":Owner>=0&&BuzRules.Team(i)==BuzRules.Team(Owner)?"ESCORT":Owner>=0?"INTERCEPT":"CONTEST").Append(i==5?"":"\n");return text.ToString();}}public override string Results=>(Winner>=0?teams[Winner]+" WINS":"TIED")+"\n\n"+score[0]+" : "+score[1]+"\n"+Deliveries+" physical cargo deliveries · "+Breaks+" legal rope breaks";
 protected override void BeginGame(){score[0]=score[1]=0;Clock=Age=0;SuddenDeath=false;Winner=-1;Attachments=Breaks=Deliveries=Recoveries=TruckRecoveries=0;ResetField();}
 void RemoveTow(){if(tow!=null){Destroy(tow);tow=null;}Owner=-1;rope.enabled=false;}
 void ResetField(){RemoveTow();previousCarrier=-1;reclaimUntil=attachProtectedUntil=looseUntil=0;for(int i=0;i<6;i++){float z=i<3?-25:25;trucks[i].visuals.gameObject.SetActive(true);trucks[i].Prepare(new Vector3((i%3-1)*11,.55f,z),Quaternion.Euler(0,i<3?0:180,0));trucks[i].Power(false);trucks[i].body.isKinematic=true;think[i]=noProgress[i]=reverse[i]=inverted[i]=recovering[i]=outsideAge[i]=0;lastTruck[i]=trucks[i].body.position;trucks[i].GetComponent<BuzImpact>().Clear();}cargo.isKinematic=false;cargo.position=new Vector3(0,1.5f,0);cargo.rotation=Quaternion.identity;cargo.linearVelocity=cargo.angularVelocity=Vector3.zero;for(int i=0;i<floppy.Length;i++){floppy[i].isKinematic=false;floppy[i].position=cargo.position+floppyOffsets[i];floppy[i].rotation=Quaternion.identity;floppy[i].linearVelocity=floppy[i].angularVelocity=Vector3.zero;}cargo.isKinematic=true;foreach(var f in floppy)f.isKinematic=true;stuckAge=outAge=0;lastCargo=cargo.position;contacts.Clear();Phase=BuzPhase.Countdown;Age=0;available=Clock+.5f;cab?.Layout();Gate();}
 bool Clear(int slot,bool staticOnly=false){var from=trucks[slot].body.worldCenterOfMass;var delta=cargo.worldCenterOfMass-from;int n=Physics.RaycastNonAlloc(from,delta.normalized,rays,delta.magnitude,~0,QueryTriggerInteraction.Ignore);var hits=n==rays.Length?Physics.RaycastAll(from,delta.normalized,delta.magnitude,~0,QueryTriggerInteraction.Ignore):null;int count=hits!=null?hits.Length:n;for(int i=0;i<count;i++){var hit=hits!=null?hits[i]:rays[i];if(hit.rigidbody==trucks[slot].body||hit.rigidbody==cargo||Array.IndexOf(floppy,hit.rigidbody)>=0||staticOnly&&hit.rigidbody!=null)continue;return false;}return true;}
 public bool CanGrab(int slot)=>Phase==BuzPhase.Playing&&Owner<0&&Clock>=available&&slot>=0&&slot<6&&(slot!=previousCarrier||Clock>=reclaimUntil)&&!Recovering(slot)&&Vector3.Distance(trucks[slot].body.worldCenterOfMass,cargo.worldCenterOfMass)<=7&&Clear(slot);
 public bool Grab(int slot){if(Phase!=BuzPhase.Playing||Clock<available||slot<0||slot>=6)return false;if(Owner==slot){Detach(false);return true;}if(!CanGrab(slot))return false;tow=cargo.gameObject.AddComponent<SpringJoint>();tow.autoConfigureConnectedAnchor=false;tow.anchor=Vector3.zero;tow.connectedBody=trucks[slot].body;tow.connectedAnchor=trucks[slot].transform.InverseTransformPoint(trucks[slot].shape.ClosestPoint(cargo.worldCenterOfMass));float distance=Vector3.Distance(trucks[slot].transform.TransformPoint(tow.connectedAnchor),cargo.worldCenterOfMass);tow.minDistance=Mathf.Clamp(distance*.6f,1,3);tow.maxDistance=Mathf.Clamp(distance,3.8f,6.5f);tow.spring=95;tow.damper=35;tow.tolerance=.05f;tow.breakForce=650;tow.breakTorque=float.PositiveInfinity;tow.enableCollision=false;Owner=slot;available=Clock+.12f;attachProtectedUntil=Clock+.35f;stuckAge=0;lastCargo=cargo.position;contacts.Clear();trucks[slot].GetComponent<BuzImpact>().Clear();Attachments++;rope.enabled=true;feedback.Play(3,0,true);return true;}
 void Detach(bool broken){if(Owner<0)return;int previous=Owner;RemoveTow();previousCarrier=previous;reclaimUntil=Clock+1.4f;available=Clock+.12f;looseUntil=Clock+1.4f;stuckAge=0;lastCargo=cargo.position;contacts.Clear();if(broken){Breaks++;Pulse(previous,.3f,.12f);}feedback.Play(2,0,true);}
 public void Contact(int a,int b,Collision c){if(Phase!=BuzPhase.Playing)return;float speed=0;for(int i=0;i<c.contactCount;i++)speed=Mathf.Max(speed,Mathf.Abs(Vector3.Dot(previousVelocity[a]-previousVelocity[b],c.GetContact(i).normal)));if(a<b){feedback.Play(1,speed);if(speed>5){Pulse(a,.18f,.09f);Pulse(b,.18f,.09f);}}bool mainBody=false;for(int k=0;k<c.contactCount;k++){var p=c.GetContact(k);if(p.thisCollider==trucks[a].shape&&p.otherCollider==trucks[b].shape||p.thisCollider==trucks[b].shape&&p.otherCollider==trucks[a].shape)mainBody=true;}if(mainBody&&Clock>=available&&Clock>=attachProtectedUntil&&BuzRules.Breaks(Owner,a,b,speed))Detach(true);}
 Vector2 AI(int i,float dt){var t=trucks[i];var p=t.body.position;float d=(int)setup.players[i].difficulty;if(reverse[i]>0){reverse[i]-=dt;return new Vector2(i%2==0?1:-1,-.7f);}if(Clock<think[i])return ai[i];think[i]=Clock+Mathf.Lerp(.3f,.1f,d*.5f);Vector3 target;float desired=12;if(i==Owner){float z=i<3?-56:56;target=Mathf.Abs(cargo.position.x)>44?new Vector3(Mathf.Sign(cargo.position.x)*37,0,Mathf.Clamp(p.z+(i<3?-14:14),-55,55)):new Vector3(Mathf.Clamp(-cargo.position.x*.25f,-5,5),0,z);desired=Vector3.Distance(p,target)>8?12:6;}else if(Owner>=0){var owner=trucks[Owner];bool friendly=BuzRules.Team(i)==BuzRules.Team(Owner);if(friendly){target=owner.body.position+owner.transform.forward*7+owner.transform.right*(i%2==0?6:-6);desired=10;}else{target=owner.body.position+Vector3.ClampMagnitude(owner.body.linearVelocity*.7f,8);desired=15;}}else{float best=float.PositiveInfinity;int nearest=-1;for(int j=0;j<6;j++)if(BuzRules.Team(j)==BuzRules.Team(i)){float distance=(trucks[j].body.position-cargo.position).sqrMagnitude;if(distance<best){best=distance;nearest=j;}}target=cargo.position+(nearest==i?Vector3.zero:new Vector3(i%2==0?7:-7,0,i<3?7:-7));desired=nearest==i?10:8;}
 var delta=Vector3.ProjectOnPlane(target-p,Vector3.up);float angle=Vector3.SignedAngle(t.transform.forward,delta,Vector3.up);bool back=delta.magnitude<8&&Mathf.Abs(angle)>115;float speed=Vector3.Dot(t.body.linearVelocity,t.transform.forward);if(Mathf.Abs(angle)>45&&!back)desired*=.5f;float steer=Mathf.Clamp((back?Mathf.DeltaAngle(angle,180):angle)/30,-1,1)*(back?-1:1);ai[i]=new Vector2(steer,Mathf.Clamp(((back?-desired:desired)-speed)*.6f,-1,1));if((p-lastTruck[i]).sqrMagnitude<.1f&&Mathf.Abs(ai[i].y)>.3f)noProgress[i]+=.2f;else{noProgress[i]=0;lastTruck[i]=p;}if(noProgress[i]>2){reverse[i]=1;noProgress[i]=0;}return ai[i];}
 protected override void Simulate(float dt){Age+=dt;if(Phase==BuzPhase.Countdown){if(Age>3){Phase=BuzPhase.Playing;Age=0;cargo.isKinematic=false;foreach(var f in floppy)f.isKinematic=false;for(int i=0;i<6;i++){trucks[i].body.isKinematic=false;trucks[i].Power(true);}feedback.Play(0,0,true);}return;}if(Phase==BuzPhase.Celebration||Phase==BuzPhase.Recovery){if(Age>2.5f){if(Winner>=0){Phase=BuzPhase.Complete;EndMatch();}else ResetField();}return;}if(Phase!=BuzPhase.Playing)return;Clock+=dt;for(int i=0;i<6;i++){previousVelocity[i]=trucks[i].body.linearVelocity;if(RecoverTruck(i,dt))continue;bool bot=setup.players[i].source==BowlingSource.AI;trucks[i].steerAngle=Mathf.Lerp(54,39,Mathf.Clamp01(trucks[i].body.linearVelocity.magnitude/14));trucks[i].TickDrive(bot?AI(i,dt):commands[i]);if(bot){if(Owner<0&&Clock>=available)Grab(i);}else if(actions[i])Grab(i);}
 if(Owner>=0&&(tow==null||Vector3.Distance(TowAnchor(Owner),cargo.position)>9.5f))Detach(true);if(Owner>=0&&BuzRules.EntireCargo(CargoScoringBounds,BuzRules.Team(Owner))){scorer=BuzRules.Team(Owner);score[scorer]++;Deliveries++;if(SuddenDeath)Winner=scorer;RemoveTow();Phase=BuzPhase.Celebration;Age=0;foreach(var t in trucks)t.Power(false);feedback.Play(5,0,true);Gate();Debug.Log("BUZ_DELIVERY team="+scorer+" score="+score[0]+":"+score[1]+" clock="+Clock);return;}
 if(!SuddenDeath&&Clock>=300){if(score[0]!=score[1]){Winner=score[0]>score[1]?0:1;Phase=BuzPhase.Complete;EndMatch();return;}SuddenDeath=true;feedback.Play(4,0,true);}
 bool far=cargo.position.y< -6||Mathf.Abs(cargo.position.x)>54.8f||Mathf.Abs(cargo.position.z)>61.8f;float nearest=100;foreach(var t in trucks)nearest=Mathf.Min(nearest,Vector3.Distance(t.body.position,cargo.position));if((cargo.position-lastCargo).sqrMagnitude>.65f*.65f){lastCargo=cargo.position;stuckAge=0;}else stuckAge+=dt;bool wallPin=Owner>=0&&Mathf.Min(Time.time-contacts.LastWallContact,Time.time-trucks[Owner].GetComponent<BuzImpact>().LastBarrierContact)<1&&stuckAge>18&&Mathf.Abs(trucks[Owner].command.y)>.35f&&trucks[Owner].body.linearVelocity.sqrMagnitude<1;bool reachable=false;if(Owner<0&&stuckAge>12)for(int i=0;i<6;i++)if(Vector3.Distance(trucks[i].body.position,cargo.position)<9&&Clear(i,true)){reachable=true;break;}bool abandoned=Owner<0&&!reachable&&stuckAge>12;outAge=far?outAge+dt:0;if(outAge>1.5f||abandoned||wallPin){RemoveTow();Phase=BuzPhase.Recovery;Age=0;Recoveries++;feedback.Play(4,0,true);Gate();}}
 bool RecoverTruck(int i,float dt){var t=trucks[i];if(recovering[i]>0){recovering[i]-=dt;if(recovering[i]<=0){bool found=false;for(int n=0;n<10;n++){var p=new Vector3((n%5-2)*9,.55f,(i<3?-1:1)*(25+n/5*8));if(Physics.CheckBox(p+Vector3.up*.7f,new Vector3(1.5f,1.3f,2.5f),Quaternion.identity,1<<2,QueryTriggerInteraction.Ignore))continue;t.Prepare(p,Quaternion.Euler(0,i<3?0:180,0));t.GetComponent<BuzImpact>().Clear();outsideAge[i]=noProgress[i]=reverse[i]=0;lastTruck[i]=p;found=true;break;}if(!found)recovering[i]=.5f;}return true;}var position=t.body.position;inverted[i]=Vector3.Dot(t.body.rotation*Vector3.up,Vector3.up)<.2f&&t.body.linearVelocity.sqrMagnitude<1?inverted[i]+dt:0;bool outside=position.y< -6||Mathf.Abs(position.x)>54.8f||Mathf.Abs(position.z)>61.8f;outsideAge[i]=outside?outsideAge[i]+dt:0;if(inverted[i]<5&&outsideAge[i]<1)return false;if(Owner==i)Detach(true);t.Power(false);recovering[i]=1.5f;inverted[i]=0;TruckRecoveries++;feedback.Play(4,0,true);Debug.Log("BUZ_TRUCK_RECOVERY slot="+i+" genuine="+(outside?"out-of-bounds":"stationary inverted")+" at="+position);return true;}
 public Vector3 TowAnchor(int slot)=>trucks[slot].body.position+trucks[slot].body.rotation*Vector3.Scale(Owner==slot&&tow!=null?tow.connectedAnchor:new Vector3(0,.2f,-2),trucks[slot].transform.lossyScale);public bool Recovering(int slot)=>recovering[slot]>0;public Bounds CargoScoringBounds{get{var bounds=cargoShape.bounds;foreach(var part in floppy)if(part!=null&&part.TryGetComponent<Collider>(out var shape))bounds.Encapsulate(shape.bounds);return bounds;}}
 protected override void Present(float dt){if(trucks==null)return;for(int i=0;i<6;i++){identities[i].transform.position=trucks[i].body.position+Vector3.up*2.5f;identities[i].text=setup.players[i].name;identities[i].color=setup.players[i].color;}for(int i=0;i<2;i++)corralNames[i].text=teams[i]+"\nHOME CORRAL";if(Owner>=0&&rope.enabled){var a=TowAnchor(Owner);var b=cargo.position;for(int i=0;i<7;i++){float t=i/6f;rope.SetPosition(i,Vector3.Lerp(a,b,t)+Vector3.down*(Mathf.Sin(t*Mathf.PI)*.35f));}}}
 public override void ExtraAction(string key){if(key=="teamsetup"&&!Running)menus.Show((SportsEventScreen)8);else if(key=="teamback")menus.Show(SportsEventScreen.Setup);}
 public override string ViewText(int view){int i=cab.owners[view];return setup.players[i].name+" · "+teams[BuzRules.Team(i)]+" · "+score[0]+":"+score[1]+" · "+Mathf.CeilToInt(300-Clock)+"s\n"+(Owner==i?"TOWING · ACTION RELEASE":CanGrab(i)?"SHEEP IN RANGE · ACTION ATTACH":Owner>=0&&BuzRules.Team(i)!=BuzRules.Team(Owner)?"RAM THE CARRIER · CLAIM THE LOOSE SHEEP":Status)+"\n"+Controls(i);}
 protected override void StopGame(){cab?.Release();RemoveTow();if(trucks!=null)foreach(var t in trucks)t.Park(t.body.position);if(cargo!=null){if(!cargo.isKinematic)cargo.linearVelocity=cargo.angularVelocity=Vector3.zero;cargo.isKinematic=true;}if(floppy!=null)foreach(var f in floppy)f.isKinematic=true;}protected override void StopSounds(){if(trucks!=null)foreach(var t in trucks)t.StopSound();}
}
